   * Sets the Response object for the current request.
   *
   * @param _res - The Response object to set.
   */
  set res(_res: Response | undefined) {
    if (this.#res && _res) {
      _res = createResponseInstance(_res.body, _res)
      for (const [k, v] of this.#res.headers.entries()) {
        if (k === 'content-type' || k === 'set-cookie') {
          continue
        }
        _res.headers.set(k, v)
      }
      for (const cookie of this.#res.headers.getSetCookie()) {
        _res.headers.append('set-cookie', cookie)
      }
    }
    this.#res = _res
    this.finalized = true
  }

  /**
   * `.render()` can create a response within a layout.
   *
   * @see {@link https://hono.dev/docs/api/context#render-setrenderer}
   *
  })

  it('Should set cookie headers when re-assigning Response to `c.res`', () => {
    const cookies = ['foo=bar; Path=/', 'foo2=bar2; Path=/']
    const res = new Response(null)
    res.headers.append('set-cookie', cookies[0])
    res.headers.append('set-cookie', cookies[1])
    c.res = res
    expect(c.res.headers.getSetCookie().length).toBe(2)

    // Re-assign
    const newCookies = ['foo3=bar3; Path=/']
    const newResponse = new Response(null)
    newResponse.headers.append('set-cookie', newCookies[0])
    c.res = newResponse
    const assignedCookies = c.res.headers.getSetCookie()
    expect(assignedCookies.length).toBe(cookies.length + newCookies.length)
    expect(assignedCookies).toEqual([...newCookies, ...cookies])
  })

  it('Should merge cookies set on `c.res` with cookies on the assigned Response', () => {
    c.res.headers.append('set-cookie', 'middleware=1; Path=/')
    c.res = new Response('body', {
      headers: {
        'Set-Cookie': 'handler=1; Path=/',
      },
    })

    const cookies = c.res.headers.getSetCookie()
    expect(cookies.length).toBe(2)
    expect(cookies).toContain('middleware=1; Path=/')
    expect(cookies).toContain('handler=1; Path=/')
  })

  it('Should merge multiple cookies when re-assigning Response to `c.res`', () => {
    c.res.headers.append('set-cookie', 'middleware=1; Path=/')
    c.res.headers.append('set-cookie', 'middleware=2; Path=/')
    c.res = new Response('body', {
      headers: [
        ['Set-Cookie', 'handler=1; Path=/'],
        ['Set-Cookie', 'handler=2; Path=/'],
      ],
    })

    const cookies = c.res.headers.getSetCookie()
    expect(cookies.length).toBe(4)
    expect(cookies).toEqual([
      'handler=1; Path=/',
      'handler=2; Path=/',
      'middleware=1; Path=/',
      'middleware=2; Path=/',
    ])
  })

  it('Should keep previous cookies in response headers', () => {
    c.res.headers.append('set-cookie', 'foo=bar; Path=/')
    setCookie(c, 'foo2', 'bar2', { path: '/' })
    const res = c.json({ message: 'Hello' })
    const cookies = res.headers.getSetCookie()
    expect(cookies.includes('foo=bar; Path=/')).toBe(true)
    expect(cookies.includes('foo2=bar2; Path=/')).toBe(true)
  })

